#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_ifc2x3_all_four_actual_declaration_routes_preserve_decimals_and_warnings(){
    use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};
    semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("IFC SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
    for subset in ["*","cv20","sav","cobie"]{let mut snapshot=fixture();if subset=="sav"{snapshot.document.instances.push(Part21Instance{id:42,entities:vec![("IFCSTRUCTURALANALYSISMODEL".into(),vec![])]});}let database=project(&snapshot);let dialect=ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:subset.into()};let expected=snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().diagnostics;for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let exported=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(exported.diagnostics,expected);let imported=io_import_sqlite_snapshot::<Ifc2x3Snapshot>(&dialect,&exported.value,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(imported.value,snapshot);assert_eq!(imported.diagnostics,expected);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}}
}
