fn sqlite_snapshot_ifc2x3_refuses_corrupt_decimal_optional_owner_forests_and_limits(){let original=project(&fixture());for mutation in 0..8{let mut db=original.clone();match mutation{0=>db.table_mut("ifc2x3_entity_argument").unwrap().rows[0].values[3]=SqliteValue::Integer(999),1=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="ref").unwrap().values[9]=SqliteValue::Text("00".into()),2=>db.table_mut("ifc2x3_instance").unwrap().rows[1].values[3]=SqliteValue::Text("0".into()),3=>db.table_mut("ifc2x3_document").unwrap().rows[0].values[3]=SqliteValue::Null,4=>db.table_mut("ifc2x3_file_name_argument").unwrap().rows[0].values[2]=SqliteValue::Integer(1),5=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[5]=SqliteValue::Integer(4294967296),6=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[6]=SqliteValue::Integer(2147483648),_=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[3]=SqliteValue::Integer(2)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_allocation_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(Ifc2x3Snapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
