 let payload=cohort_ifc2x3_payload(&cohort_ifc2x3("文🌠".repeat(20000)),encoding);let mut reached=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{reached=true;false}else{true}};
