#[test]
fn sqlite_snapshot_ifc2x3_owned_decimal_coefficients_survive_semantic_files_without_display() {
    use semio_framework_value::{FromValue, ToValue};
    use std::io::Write;
    use std::process::{Command, Stdio};
    let corpus: serde_json::Value = serde_json::from_str(include_str!("../../../../../../../../../../📇️registry/🧬️contract/📐️part21/🧫️fixtures/🚦️sqlite-cohort/🔣️.json")).unwrap();
    let mut snapshot = fixture();
    snapshot.document.instances[0].entities[0].1 = corpus["decimalOwnedExtras"].as_array().unwrap().iter().map(|row| {
        let decimal = Part21Decimal { negative: row["negative"].as_bool().unwrap(), coefficient: row["coefficient"].as_str().unwrap().into(), scale: u32::try_from(row["scale"].as_u64().unwrap()).unwrap(), exponent: row.get("exponent").map(|v| i32::try_from(v.as_i64().unwrap()).unwrap()) };
        assert_eq!(<Part21Decimal as FromValue>::from_value(decimal.to_value()).unwrap(), decimal);
        Part21Value::Real(decimal)
    }).collect();
    let bytes = export_sqlite_database(&project(&snapshot), SqliteDatabaseLimits::default(), &mut |_| true).unwrap();
    let oracle = "import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query(\"SELECT decimal_coefficient FROM ifc2x3_value WHERE kind='real' ORDER BY id\").all();if(JSON.stringify(rows)!==JSON.stringify([{decimal_coefficient:''},{decimal_coefficient:'1x'}]))throw Error('literal coefficients');await Bun.write(Bun.stdout,db.serialize());db.close();";
    let mut child = Command::new("bun").args(["-e", oracle]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
    child.stdin.take().unwrap().write_all(&bytes).unwrap();
    let result = child.wait_with_output().unwrap();
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    assert_eq!(restore(&import_sqlite_database(&result.stdout, SqliteDatabaseLimits::default(), &mut |_| true).unwrap()).unwrap(), snapshot);
}

#[test]
fn sqlite_snapshot_ifc2x3_surrogate_root_header_ids_are_relationships_not_fixed_ones() {
    use std::{io::Write, process::{Command, Stdio}};
    let corpus: serde_json::Value = serde_json::from_str(include_str!("../../../../../../../../../../📇️registry/🧬️contract/📐️part21/🧫️fixtures/🚦️sqlite-cohort/🔣️.json")).unwrap();
    let snapshot = fixture(); let original = project(&snapshot); let limits = SqliteDatabaseLimits::default();
    let offset = corpus["nativeOwned"]["surrogateOffset"].as_i64().unwrap();
    let script = format!("import{{Database}}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));db.exec('PRAGMA foreign_keys=OFF');for(const{{name}}of db.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){{const key=db.query('PRAGMA table_info('+name+')').all().find(column=>column.pk===1).name;const links=db.query('PRAGMA foreign_key_list('+name+')').all();db.exec('UPDATE '+name+' SET '+[key+'='+key+'+{offset}',...links.filter(link=>link.from!==key).map(link=>link.from+'='+link.from+'+{offset}')].join(','));}}if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('renumber integrity');await Bun.write(Bun.stdout,db.serialize());db.close();");
    let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&export_sqlite_database(&original,limits,&mut |_|true).unwrap()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let database=import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap();let restored=restore(&database).expect("normalized surrogate relationships must retain exact root/header ownership");assert_eq!(project(&restored),original);
}

#[test]
fn sqlite_snapshot_ifc2x3_controlled_native_owned_frame_preserves_literal_schema_and_all_variants() {
    let corpus: serde_json::Value = serde_json::from_str(include_str!("../../../../../../../../../../📇️registry/🧬️contract/📐️part21/🧫️fixtures/🚦️sqlite-cohort/🔣️.json")).unwrap();
    let mut snapshot = fixture(); snapshot.schema = corpus["nativeOwned"]["schema"].as_str().unwrap().into();
    let expected = project(&snapshot); let limits = SqliteDatabaseLimits::default();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text] {
        let payload = snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).expect("actual owner must produce full literal Native state");
        let restored = <Ifc2x3Snapshot as ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).expect("actual owner must construct full literal Native state");
        assert_eq!(project(&restored),expected);
        let codec = <Ifc2x3Snapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
        let dialect = store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:"*".into()};
        assert_eq!((codec.export)(&snapshot.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value,expected);
        let reconstructed = (codec.import)(&snapshot.schema,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;
        let roundtrip = <Ifc2x3Snapshot as ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&reconstructed,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(); assert_eq!(project(&roundtrip),expected);
    }
}

#[test]
fn sqlite_snapshot_ifc2x3_owned_decimal_coefficient_is_literal_state_not_exchange_validation() {
    assert!(Part21Decimal::parse("1x").is_err());assert!(Part21Decimal::parse("").is_err());
    use std::{io::Write,process::{Command,Stdio}};
    let cohort:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../📇️registry/🧬️contract/📐️part21/🧫️fixtures/🚦️sqlite-cohort/🔣️.json")).unwrap();
    for coefficient in cohort["nativeOwned"]["decimalCoefficients"].as_array().unwrap(){
        let mut snapshot=fixture();
        snapshot.document.instances[0].entities[0].1=vec![Part21Value::Real(semio_s_artifact_stdio_contract::part21::Part21Decimal{negative:true,coefficient:coefficient.as_str().unwrap().into(),scale:u32::MAX,exponent:Some(i32::MIN)})];
        let database=project(&snapshot);
        let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
        let script=r#"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query("SELECT decimal_negative,decimal_coefficient,decimal_scale,decimal_exponent FROM ifc2x3_value WHERE kind='real' ORDER BY id").all();await Bun.write(Bun.stdout,JSON.stringify(rows));db.close();"#;
        let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let rows:serde_json::Value=serde_json::from_slice(&result.stdout).unwrap();assert!(rows.as_array().unwrap().iter().any(|row|row["decimal_negative"]==1&&row["decimal_coefficient"]==*coefficient&&row["decimal_scale"]==u32::MAX&&row["decimal_exponent"]==i32::MIN));
        let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),database);
    }
}

#[test]
fn sqlite_snapshot_ifc2x3_actual_removal_keeps_literal_references_through_erased_native_and_sqlite_file() {
 use crate::standards::v2x3::subsets::base::schema::mutations::{apply_ifc2x3_mutation,Ifc2x3Mutation,remove_instance::RemoveInstance};
 use std::{io::Write,process::{Command,Stdio}};
 fn edit(value:&mut Part21Value,from:u64,to:u64){match value{Part21Value::Ref(word)if *word==from=>*word=to,Part21Value::List(items)|Part21Value::Typed{items,..}=>for item in items{edit(item,from,to)},_=>{}}}
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧩️intermediate/🔣️.json")).unwrap();
 let limits=SqliteDatabaseLimits::default();let provider=<Ifc2x3Snapshot as ArtifactSqliteSnapshot>::sqlite_codec();
 let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:"*".into()};
 for case_ in corpus["cases"].as_array().unwrap(){
  let removed=case_["removedId"].as_str().unwrap().parse::<u64>().unwrap();let replacement=corpus["editReference"].as_str().unwrap().parse::<u64>().unwrap();
  let mut snapshot=fixture();snapshot.schema=corpus["schema"].as_str().unwrap().into();let mut expected=snapshot.clone();expected.document.instances.retain(|instance|instance.id!=removed);
  let outcome=apply_ifc2x3_mutation(&mut snapshot,&Ifc2x3Mutation::RemoveInstance(RemoveInstance{id:removed}));assert!(outcome.messages().is_empty());
  assert_eq!(<Ifc2x3Snapshot as store::ArtifactPack>::encode_pack(&snapshot),<Ifc2x3Snapshot as store::ArtifactPack>::encode_pack(&expected));
  let semantic=project(&snapshot);assert_eq!(semantic,project(&expected));
  for value in expected.document.header.file_description.iter_mut().chain(&mut expected.document.header.file_name).chain(&mut expected.document.header.file_schema){edit(value,removed,replacement);}
  for instance in &mut expected.document.instances{for(_,arguments)in &mut instance.entities{for value in arguments{edit(value,removed,replacement);}}}
  for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
   let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
   let decoded=Ifc2x3Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(project(&decoded),semantic);
   let database=(provider.export)(&snapshot.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(database,semantic);
   let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();
   let oracle=r#"import{Database}from'bun:sqlite';const expected=EXPECTED_REFERENCES;const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query("SELECT v.reference_instance_id AS literal,e.instance_id AS resolved FROM ifc2x3_value AS v LEFT JOIN ifc2x3_instance AS e ON e.id=v.reference_instance_row_id WHERE v.kind='ref' ORDER BY v.id").all();if(JSON.stringify(rows)!==JSON.stringify(expected))throw Error('literal/resolved reference state');db.query("UPDATE ifc2x3_value SET reference_instance_id=? WHERE kind='ref' AND reference_instance_row_id IS NULL").run(EDIT_LITERAL);await Bun.write(Bun.stdout,db.serialize());db.close();"#.replace("EXPECTED_REFERENCES",&serde_json::to_string(&case_["references"]).unwrap()).replace("EDIT_LITERAL",&serde_json::to_string(&corpus["editReference"]).unwrap());
   let mut child=Command::new("bun").args(["-e",&oracle]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
   let edited=import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap();let imported=(provider.import)(&snapshot.schema,&dialect,edited,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;
   let actual=Ifc2x3Snapshot::decode_sqlite_snapshot_native(&imported,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(project(&actual),project(&expected));
   eprintln!("[DEBUG] IFC2x3 actual removal complete erased/file owner {removed} {encoding:?}");
  }
 }
}
